CREATE TABLE `simops_transfer_decisions` (`tenant` text NOT NULL, `job` text NOT NULL, `round` integer NOT NULL, `decision` text NOT NULL CHECK(`decision` IN('offered','accepted','rejected')), `target` text NOT NULL, `actor` text NOT NULL, `reason` text, `at` integer NOT NULL, PRIMARY KEY(`tenant`,`job`,`round`,`decision`), FOREIGN KEY(`tenant`,`job`) REFERENCES `simops_jobs`(`tenant`,`id`));
